def trace_spectrum(k: int) -> set:
    S = (0, -1, 1, 0)
    T = (1, 1, 0, 1)
    gens = [S, T, (0,1,-1,0), (1,-1,0,1)]
    current = {(1,0,0,1)}
    traces = {2}
    for _ in range(k):
        nxt = set()
        for g in current:
            for h in gens:
                p = (g[0]*h[0]+g[1]*h[2], g[0]*h[1]+g[1]*h[3], g[2]*h[0]+g[3]*h[2], g[2]*h[1]+g[3]*h[3])
                traces.add(p[0]+p[3])
                nxt.add(p)
        current = nxt
    return traces

def fricke_vogt_check(A, B):
    def mul(a,b): return (a[0]*b[0]+a[1]*b[2], a[0]*b[1]+a[1]*b[3], a[2]*b[0]+a[3]*b[2], a[2]*b[1]+a[3]*b[3])
    def inv(m): return (m[3],-m[1],-m[2],m[0])
    def tr(m): return m[0]+m[3]
    AB = mul(A,B)
    comm = mul(mul(AB, inv(A)), inv(B))
    return tr(A)**2 + tr(B)**2 + tr(AB)**2 == tr(A)*tr(B)*tr(AB) + tr(comm) + 2
